public class BinaryWriter {

    public static String toBinary(int n) {
        if (n == 0) {
            return "0";
        }
        StringBuilder bits = new StringBuilder();
        while (n > 0) {
            bits.append(n % 2);
            n = n / 2;
        }
        return bits.reverse().toString();
    }
}
